def write_or_fail(rows, path):
    for row in rows:
        if "#" in row:
            raise ValueError("Invalid row content")

    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as file:
        for row in rows:
            clean_row = row.strip()
            if clean_row:
                file.write(clean_row + "\n")
